begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1709 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:5ff00bfd7ee36f8d690360b2' and md5(to_jsonb(t)::text)='fcec94cff5c5353b84deafd2876f3cca')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:5ff00bfd7ee36f8d690360b2';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_29a98243d423565f$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tomo contiene la información y los ensalmos necesarios para crear un tipo concreto de gólem. Tu GM elige el tipo o lo determina al azar. Para descifrar y usar el manual, debes ser un lanzador de conjuros con al menos dos espacios de conjuro de nivel 5. Si una criatura no puede usar un manual de gólems y trate de leerlo, sufrirá 6d6 de daño psíquico.\n\n1–5 · Arcilla · 30 días · 65 000 po\n6–17 · Carne · 60 días · 50 000 po\n18 · Hierro · 120 días · 100 000 po\n19–20 · Piedra · 90 días · 80 000 po\n\nPara crear un gólem, debes dedicar el tiempo mostrado en la tabla, trabajar sin interrupciones con el manual a mano y no descansar durante más de 8 horas al día. También debes pagar el precio especificado para comprar los suministros.\n\nEn cuanto hayas acabado de crear al gólem, el libro arderá en llamas sobrenaturales. El gólem cobrará vida cuando se esparzan sobre él las cenizas del manual. Estará bajo tu control, entenderá tus órdenes verbales y las obedecerá.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_29a98243d423565f$::jsonb,true),'{rules,personalDescription}',$text_fce6f5e6e16a8c6f$"Este tomo contiene la información y los ensalmos necesarios para hacer un tipo concreto de gólem. El DM elige el tipo o lo determina al azar. Para poder descifrar y usar el manual, tienes que ser un lanzador de conjuros con al menos dos espacios de conjuro de nivel 5. Una criatura que no pueda usar el manual de gólems pero intente leerlo, recibirá 6d6 de daño psíquico.\n\n1-5 - Manual de Gólems de Arcilla - 30 días - 65,000 PO\n6-17 - Manual de los Gólems de Carne - 60 días - 50,000 GPO\n18 - Manual de los Gólems de Hierro - 120 días - 100,000 PO\n19-20 - Manual de los Gólems de Piedra - 90 días - 80,000 PO\n\nPara crear un gólem, debes emplear la cantidad de tiempo mostrada en la tabla, trabajando sin interrupción con el libro a mano y sin descansar más de 8 horas al día. También has de pagar el coste indicado para comprar suministros. Una vez terminas de crear el gólem, el libro arde en llamas arcanas. El gólem se vuelve animado cuando se esparcen sobre él las cenizas del manual. Estará bajo tu control, y entenderá y obedecerá tus órdenes verbales. Su perfil se encuentra en el Monster Manual."$text_fce6f5e6e16a8c6f$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:5ff00bfd7ee36f8d690360b2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:603a7612a52f1b0dc500319a' and md5(to_jsonb(t)::text)='607d840d489c279de840b4306f4a1c18')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:603a7612a52f1b0dc500319a';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_7abd4351a086fcc3$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás una velocidad trepando igual a tu velocidad caminando durante 1 hora. Durante ese tiempo, tendrás ventaja en las pruebas de Fuerza (Atletismo) que hagas para trepar. La poción se separa en tres capas (marrón, plateada y gris) que parecen los estratos de una roca. Si agitas la botella, los colores no se mezclan.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_7abd4351a086fcc3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:603a7612a52f1b0dc500319a';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:607b667eddf76a4b1dda4c2e' and md5(to_jsonb(t)::text)='62741735b51eb8bd71e8b3c358dee270')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:607b667eddf76a4b1dda4c2e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_fa61d6dec4567eb9$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"En el exterior de este recipiente se forman gotitas de un aceite turbio y gris que se evaporan rápidamente. El aceite puede cubrir a una criatura Mediana o más pequeña, así como el equipo que vista o lleve. Se necesita un vial extra por cada categoría de tamaño por encima de Mediano. Aplicar el aceite lleva 10 minutos. La criatura afectada obtiene el efecto del conjuro excursión etérea durante 1 hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_fa61d6dec4567eb9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:607b667eddf76a4b1dda4c2e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:61f89fe62d631f3cdc73f2bc' and md5(to_jsonb(t)::text)='14ba85557c0fb5441cfbf17455ddaf3e')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:61f89fe62d631f3cdc73f2bc';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_e0f585482b8941ad$"Objeto · Precio base · Peso\nÚtiles de escalada · 25 po · 12 lb\n\nÚtiles de escalada. Entre estos útiles se incluyen pitones especiales, puntas para las botas y un arnés. Puedes usar una acción para anclarte mediante estos útiles. Cuando lo hayas hecho, no podrás caer más de 7,5 m desde el punto en el que te ancles y no podrás subir más de 7,5 m de ese punto sin desanclarte.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_e0f585482b8941ad$::jsonb,true),'{features}',$text_f4c3ee5927eb8438$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles de escalada. Entre estos útiles se incluyen pitones especiales, puntas para las botas y un arnés. Puedes usar una acción para anclarte mediante estos útiles. Cuando lo hayas hecho, no podrás caer más de 7,5 m desde el punto en el que te ancles y no podrás subir más de 7,5 m de ese punto sin desanclarte.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_f4c3ee5927eb8438$::jsonb,true),'{rules,definition,description}',$text_3add5ea142dca2e1$[{"id":"official-table","rows":[["Útiles de escalada","25 po","12 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Útiles de escalada. Entre estos útiles se incluyen pitones especiales, puntas para las botas y un arnés. Puedes usar una acción para anclarte mediante estos útiles. Cuando lo hayas hecho, no podrás caer más de 7,5 m desde el punto en el que te ancles y no podrás subir más de 7,5 m de ese punto sin desanclarte.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_3add5ea142dca2e1$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:61f89fe62d631f3cdc73f2bc';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:63387bbd35bbb15be6d09c3e' and md5(to_jsonb(t)::text)='6113f945ae952651724e43457a1f0799')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:63387bbd35bbb15be6d09c3e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_e039cc2b5977900b$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este polvo, que se encuentra en paquetes pequeños, se asemeja a arena muy fina. Hay suficiente para un solo uso. Cuando empleas una acción para esparcir el polvo por el aire, tú y cada criatura y objeto que se esté a 3 m o menos de ti os volvéis invisibles durante 2d4 minutos. La duración es la misma para todos los afectados y el polvo se consume cuando la magia tiene efecto. Si una criatura afectada por el polvo ataca o lanza un conjuro, dejará de ser invisible.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_e039cc2b5977900b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:63387bbd35bbb15be6d09c3e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:656acc5366e5b282988b132f' and md5(to_jsonb(t)::text)='fd245b9149e485e346707bd75adb5e43')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:656acc5366e5b282988b132f';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_8bd213ea78ae1ebe$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"De este collar cuelgan 1d6 + 3 cuentas. Puedes usar una acción para tirar una de estas cuentas a un punto a 18 m o menos de distancia. Cuando llegue al final de su trayectoria, la cuenta explotará como si fuera un conjuro bola de fuego de nivel 3 (CD de salvación 15).\n\nPuedes arrojar varias cuentas o incluso todo el collar en una acción. Si lo haces, aumenta el nivel de la bola de fuego en 1 por cada cuenta lanzada tras la primera.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8bd213ea78ae1ebe$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:656acc5366e5b282988b132f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:65b77c0aa953b874822fa87d' and md5(to_jsonb(t)::text)='eb6a8b58b5cbf5a4272ce19c281fdfeb')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:65b77c0aa953b874822fa87d';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_833b89a0b7bc1930$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras este cuenco esté lleno de agua, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de agua, como si hubieras lanzado conjurar elemental. El cuenco no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEl cuenco tiene aproximadamente 30 cm de diámetro y la mitad de profundidad. Pesa 1,5 kg y puede contener unos 12 l.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_833b89a0b7bc1930$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:65b77c0aa953b874822fa87d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:669dbf2489ed293bb38d8a17' and md5(to_jsonb(t)::text)='784c4a092415619e2450ead3bc501e31')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:669dbf2489ed293bb38d8a17';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_77d5fd2152d45fa4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene ejercicios de coordinación y equilibrio, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Destreza aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_77d5fd2152d45fa4$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:669dbf2489ed293bb38d8a17';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:670193d18fadb992218eedf7' and md5(to_jsonb(t)::text)='780706d47a74cbffb4b58628334da2ea')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:670193d18fadb992218eedf7';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_22cd2279e0ae6955$[{"id":"official-base-table","rows":[["Martillo de guerra","15 po","2 lb","1d8 contundente","+0","Versátil","1d10"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_22cd2279e0ae6955$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_5488757723349d23$["official-base-table","property-versatile","family-rule"]$text_5488757723349d23$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:670193d18fadb992218eedf7';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6717fd92ac73e3765596e309' and md5(to_jsonb(t)::text)='09b2d5124df3d2c0c3469b97c5ed91a3')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6717fd92ac73e3765596e309';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f7f023db0ab2a01d$"Objeto · Precio base · Peso\nAljaba · 1 po · 1 lb\n\nAljaba. Una aljaba puede contener hasta 20 flechas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f7f023db0ab2a01d$::jsonb,true),'{features}',$text_ad95de5033aa8476$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Aljaba. Una aljaba puede contener hasta 20 flechas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_ad95de5033aa8476$::jsonb,true),'{rules,definition,description}',$text_2553e910a16c7cd4$[{"id":"official-table","rows":[["Aljaba","1 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Aljaba. Una aljaba puede contener hasta 20 flechas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_2553e910a16c7cd4$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6717fd92ac73e3765596e309';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:67c4d58203382e9febe67247' and md5(to_jsonb(t)::text)='8be29f2a3b62c30faa78a5c6efe99c2d')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:67c4d58203382e9febe67247';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3e0d16b332934568$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes este bastón, tendrás resistencia al daño de frío.\n\nEl bastón tiene 10 cargas. Mientras lo empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: cono de frío (5 cargas), muro de hielo (4 cargas), nube de oscurecimiento (1 carga) o tormenta de hielo (4 cargas).\n\nEl bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en agua y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3e0d16b332934568$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:67c4d58203382e9febe67247';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6807f943647e5f66904aab8c' and md5(to_jsonb(t)::text)='5ade7c5c3b703a4b76f88bfb56557280')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6807f943647e5f66904aab8c';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_c94309a253cab68c$[{"id":"official-base-table","rows":[["Cimitarra","25 po","3 lb","1d6 cortante","+0","Sutil, Ligera"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_c94309a253cab68c$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_144956692b2e784a$["official-base-table","property-finesse","property-light","family-rule"]$text_144956692b2e784a$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6807f943647e5f66904aab8c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6880ccd9a4ad0a0ca9f7b45b' and md5(to_jsonb(t)::text)='0f02f63c04941ae8714e4f106c3488e0')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6880ccd9a4ad0a0ca9f7b45b';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_040b04c1d262cc65$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"legacy-bonus-1","kind":"passive","name":"All","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las pruebas de habilidad.","showInActions":false},{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta ágata pulida contigo, recibirás un bonificador de +1 a las pruebas de característica y las tiradas de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":3,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta ágata pulida contigo, recibirás un bonificador de +1 a las pruebas de característica y las tiradas de salvación.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_040b04c1d262cc65$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6880ccd9a4ad0a0ca9f7b45b';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:68d0af6495ab84438d9efff3' and md5(to_jsonb(t)::text)='d1386b2cb8988da26e755d86daa74d81')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:68d0af6495ab84438d9efff3';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_938576b2bfb086c3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para pronunciar la palabra de activación de este bastón y lanzarlo al suelo, a 3 m o menos de ti. El bastón se convertirá en una serpiente constrictora gigante bajo tu control y actuará en su propia posición en el orden de iniciativa. Si utilizas una acción adicional para pronunciar de nuevo la palabra de activación, el bastón recuperará su forma normal en un espacio que antes ocupaba la serpiente.\n\nEn tu turno, puedes dar órdenes mentales a la serpiente si se encuentra a 18 m o menos de ti y no estás incapacitado. Tú decides la acción que llevará a cabo la serpiente y adónde se desplazará durante su siguiente turno, o puedes darle una orden general, como atacar a tus enemigos o proteger un lugar.\n\nSi los puntos de golpe de la serpiente se reducen a 0, morirá y recuperará su forma de bastón. En tal caso, el bastón se hará añicos y se destruirá. Si la serpiente recupera la forma de bastón antes de perder todos sus puntos de golpe, los recuperará todos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_938576b2bfb086c3$::jsonb,true),'{rules,personalDescription}',$text_9ecc9059b0bb2138$"Puedes usar una acción para decir la palabra de mando de este bastón y arrojarlo al suelo a 10 pies de ti. El bastón se convierte en una serpiente constrictora gigante bajo tu control y actúa por iniciativa propia. Al usar una acción adicional para decir la palabra de mando de nuevo, devuelves el bastón a su forma normal en un espacio que antes ocupaba la serpiente. \nEn tu turno, puedes ordenar mentalmente a la serpiente si está a 60 pies de ti y no estás incapacitado. Tú decides qué acción realiza la serpiente y adónde se mueve durante su próximo turno, o puedes darle una orden general, como atacar a tus enemigos o proteger una ubicación. \nSi la serpiente queda reducida a 0 puntos de golpe, muere y vuelve a su forma de bastón. Luego, el bastón se hace añicos y es destruido. Si la serpiente vuelve a su forma de bastón antes de perder todos sus puntos de golpe, los recupera todos."$text_9ecc9059b0bb2138$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:68d0af6495ab84438d9efff3';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:69d561ca2c3a56764e71cebd' and md5(to_jsonb(t)::text)='3e74d0a6534e727e423c2636667aaee8')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:69d561ca2c3a56764e71cebd';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_b21f96047a351c1b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene consejos de salud y alimentación, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Constitución aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b21f96047a351c1b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:69d561ca2c3a56764e71cebd';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6b4e8a7ee89714ac92465871' and md5(to_jsonb(t)::text)='59b9f09abf6609675d9a84358511691e')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6b4e8a7ee89714ac92465871';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5479001584507f1e$"Objeto · Precio base · Peso\nReloj de arena · 25 po · 1 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5479001584507f1e$::jsonb,true),'{rules,definition,description}',$text_6188d493dbf01d15$[{"id":"official-table","rows":[["Reloj de arena","25 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_6188d493dbf01d15$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6b4e8a7ee89714ac92465871';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6bcfc9fa2fc699815dbbb59f' and md5(to_jsonb(t)::text)='32dc99d64e1aedfe47e7b63f1ad8385f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6bcfc9fa2fc699815dbbb59f';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5efa713461f5b120$::jsonb,true),'{rules,personalDescription}',$text_a7a069502542e9db$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Mientras la espada esté contigo, también obtienes una bonificación de +1 a las tiradas de salvación.\n\nSuerte. Si llevas la espada encima, puedes recurrir a su suerte (no es necesario realizar ninguna acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación que no te gusten. Debes utilizar la segunda tirada. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer.\n\nDeseo. La espada tiene 1d4–1 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 carga y lanzar el conjuro de deseo desde ella. Esta propiedad no se puede volver a usar hasta el siguiente amanecer. La espada pierde esta propiedad si no tiene cargas."$text_a7a069502542e9db$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6bcfc9fa2fc699815dbbb59f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6be205ff80da3f50db3b8036' and md5(to_jsonb(t)::text)='9b2abee99356c08e5c923709f08dfed0')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6be205ff80da3f50db3b8036';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5efa713461f5b120$::jsonb,true),'{rules,personalDescription}',$text_a7a069502542e9db$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Mientras la espada esté contigo, también obtienes una bonificación de +1 a las tiradas de salvación.\n\nSuerte. Si llevas la espada encima, puedes recurrir a su suerte (no es necesario realizar ninguna acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación que no te gusten. Debes utilizar la segunda tirada. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer.\n\nDeseo. La espada tiene 1d4–1 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 carga y lanzar el conjuro de deseo desde ella. Esta propiedad no se puede volver a usar hasta el siguiente amanecer. La espada pierde esta propiedad si no tiene cargas."$text_a7a069502542e9db$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6be205ff80da3f50db3b8036';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6c18c45b014bd495b9788c25' and md5(to_jsonb(t)::text)='e3dc4ed299b18f38417b290f65b19e3a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6c18c45b014bd495b9788c25';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6c18c45b014bd495b9788c25';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6c22746b8f06e620d1547a10' and md5(to_jsonb(t)::text)='27e0cc6e2d05f46ed2cd212e60ce892f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6c22746b8f06e620d1547a10';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_700cde83ebc64f9c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nAbsorción (muy rara). Mientras este elipsoide de color lila claro gire alrededor de tu cabeza, podrás usar tu reacción para cancelar un conjuro de nivel 4 o inferior lanzado por una criatura que puedas ver y que solo te haga objetivo a ti.\n\nEn cuanto la piedra haya cancelado 20 niveles de conjuros, se volverá gris porque su magia se habrá agotado. Si eres el objetivo de un conjuro cuyo nivel sea superior a la cantidad de niveles de conjuro que le queden a la piedra, no podrá cancelarlo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_700cde83ebc64f9c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6c22746b8f06e620d1547a10';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6d0fa52287609369216948bf' and md5(to_jsonb(t)::text)='93bdfc34bbe305a6aafec2f452853e71')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6d0fa52287609369216948bf';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_ffeec24cc9187eb8$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un dragón con esta arma, este sufrirá 3d6 de daño adicional del tipo del arma. En lo que concierne a esta arma, “dragón” se refiere a cualquier criatura con el tipo “dragón”, incluidos seres como dragones tortuga y guivernos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ffeec24cc9187eb8$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6d0fa52287609369216948bf';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6d448708b838897d955a51eb' and md5(to_jsonb(t)::text)='bc3ffa5dd6c80a8a64582b37ce2bfca8')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6d448708b838897d955a51eb';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_025ea068512228e9$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica · Alcance normal/largo (pies)\nArco largo feroz · 50 po (solo objeto mundano base; no es el precio de la variante mágica) · 2 lb · 1d8 perforante · Munición, Pesada, A dos manos · +0 · 150/600\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_025ea068512228e9$::jsonb,true),'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_4bfc512a49fef2e9$[{"id":"official-table","rows":[["Arco largo feroz","50 po (solo objeto mundano base; no es el precio de la variante mágica)","2 lb","1d8 perforante","Munición, Pesada, A dos manos","+0","150/600"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"vicious-2014","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_4bfc512a49fef2e9$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6851a11da4c0ecd0$["official-table","vicious-2014"]$text_6851a11da4c0ecd0$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6d448708b838897d955a51eb';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6deba73e296507e887a4ed1f' and md5(to_jsonb(t)::text)='d9bad35b094b3c207cb95a0c13432bf4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6deba73e296507e887a4ed1f';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_055d6faab42f5c07$[{"id":"official-base-table","rows":[["Lucero del alba","15 po","4 lb","1d8 perforante","+0","—"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_055d6faab42f5c07$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6834d0d967473cf4$["official-base-table","family-rule"]$text_6834d0d967473cf4$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6deba73e296507e887a4ed1f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6e0e16ea21a0f01542022994' and md5(to_jsonb(t)::text)='9f12784fd146255a6d3e46aae85f82d4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6e0e16ea21a0f01542022994';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4a21ac4510aa7924$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta escoba de madera, que pesa 1,5 kg, funcionará como una escoba normal hasta que te montes en ella y pronuncies su palabra de activación. Entonces, levitará y podrás utilizarla para volar por el cielo. Tiene una velocidad volando de 15 m. Puede transportar hasta 200 kg, pero su velocidad volando se reduce a 9 m si transporta más de 100 kg. La escoba deja de levitar cuando aterrizas.\n\nPuedes ordenarle que viaje por sí misma a un lugar que esté a 1,5 km o menos de ti si pronuncias la palabra de activación, nombras el lugar y conoces el sitio en cuestión. La escoba regresará junto a ti cuando pronuncies otra palabra de activación mientras se encuentre a 1,5 km o menos de ti.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a21ac4510aa7924$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6e0e16ea21a0f01542022994';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6e83c9fa1434c8e5af25720e' and md5(to_jsonb(t)::text)='47aa7fbc82065dff2a66c9f979c22954')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6e83c9fa1434c8e5af25720e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3eedc59bbdbb862b$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de artista (40 po). Incluye una mochila, un petate, 2 disfraces, 5 velas, raciones para 5 días, una cantimplora y útiles para disfrazarse.\n\nDuración: Según su uso..","showInActions":false}]$text_3eedc59bbdbb862b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6e83c9fa1434c8e5af25720e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6eaa83f8bf3b7833d32c8ec4' and md5(to_jsonb(t)::text)='23f9bc85d6ec215157703040bbf5921e')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6eaa83f8bf3b7833d32c8ec4';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_fd3b1146f47c2c14$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delgada candela está dedicada a una deidad y comparte su alineamiento. El alineamiento de la vela se puede percibir con el conjuro detectar el bien y el mal. Tu GM elige el dios y el alineamiento asociado o determina el alineamiento al azar.\n\n1–2 · Caótico malvado\n3–4 · Caótico neutral\n5–7 · Caótico bueno\n8–9 · Neutral malvado\n10–11 · Neutral\n12–13 · Neutral bueno\n14–15 · Legal malvado\n16–17 · Legal neutral\n18–20 · Legal bueno\n\nLa magia de la vela se activa al encenderla, lo que requiere una acción. Después de arder durante 4 horas, la vela se destruye. Puedes apagarla antes de que pase ese tiempo para seguir usándola después. Resta el tiempo que ha ardido del total, en intervalos de 1 minuto.\n\nMientras permanezca encendida, la vela emitirá luz tenue en un radio de 9 m. Todas las criaturas que estén dentro de ese radio y cuyo alineamiento coincida con el de la vela realizarán las tiradas de ataque, las tiradas de salvación y las pruebas de característica con ventaja. Además, un clérigo o druida dentro del radio de la luz y cuyo alinea- miento coincida con el de la vela podrá lanzar conjuros de nivel 1 que tenga preparados sin gastar espacios de conjuro. El efecto de estos conjuros será el mismo que si se hubieran lanzado con un espacio de conjuro de nivel 1.\n\nComo alternativa, la primera vez que enciendas la vela, podrás utilizarla para lanzar el conjuro portal. Hacer esto destruirá la vela.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_fd3b1146f47c2c14$::jsonb,true),'{rules,personalDescription}',$text_acf51c9c1082391b$"Esta candela delgada está dedicada a una deidad en concreto, por lo que comparte alineamiento con ella. Este último puede ser detectado con el conjuro detectar el bien y el mal. El DM elige el dios y el alineamiento asociado o lo determina al azar. La magia de la vela se activa al encenderla, lo que requiere una acción. Después de arder durante 4 horas, es destruida. Puedes apagarla antes de que pase este tiempo para seguir usándola después. Resta el tiempo que ha ardido del total, en intervalos de l minuto.\n\nMientras permanezca encendida, la vela producirá luz tenue en un radio de 30 pies. Cualquier criatura dentro de esta luz cuyo alineamiento coincida con el de la vela realizará las tiradas de ataque, salvación y pruebas de característica con ventaja. Además, un clérigo o druida dentro de la luz y cuyo alineamiento coincida con el de la vela podrá lanzar conjuros de nivel 1 que tenga preparados sin gastar espacios de conjuro. El efecto de estos conjuros será el mismo que si se hubieran lanzado con un espacio de conjuro de nivel l.\n\nDe forma alternativa, la primera vez que enciendas la vela puedes utilizarla para lanzar el conjuro portal. Hacer esto destruye la vela."$text_acf51c9c1082391b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6eaa83f8bf3b7833d32c8ec4';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6f505d7deed241155c4e0b85' and md5(to_jsonb(t)::text)='3533b9202b814724ceb60d7b683fccaf')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:6f505d7deed241155c4e0b85';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_8c07d2b3b737b96f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene ejercicios de lógica y memoria, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Inteligencia aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8c07d2b3b737b96f$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:6f505d7deed241155c4e0b85';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:711f85d63c831b6b0310fb58' and md5(to_jsonb(t)::text)='7da3fbb7468815d57a7f38c8cd92ffe5')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:711f85d63c831b6b0310fb58';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5efa713461f5b120$::jsonb,true),'{rules,personalDescription}',$text_a7a069502542e9db$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Mientras la espada esté contigo, también obtienes una bonificación de +1 a las tiradas de salvación.\n\nSuerte. Si llevas la espada encima, puedes recurrir a su suerte (no es necesario realizar ninguna acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación que no te gusten. Debes utilizar la segunda tirada. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer.\n\nDeseo. La espada tiene 1d4–1 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 carga y lanzar el conjuro de deseo desde ella. Esta propiedad no se puede volver a usar hasta el siguiente amanecer. La espada pierde esta propiedad si no tiene cargas."$text_a7a069502542e9db$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:711f85d63c831b6b0310fb58';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:72d78d4649313d1a3f8b5b1e' and md5(to_jsonb(t)::text)='b2686fbd7a7a69c0b4b1e8048348413f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:72d78d4649313d1a3f8b5b1e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_249d9877e6e0199e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:72d78d4649313d1a3f8b5b1e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:741c6683c6d99e0c4fd359ba' and md5(to_jsonb(t)::text)='b8d07ebd9c1e00c5537bb52a14ed7dac')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:741c6683c6d99e0c4fd359ba';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_383ecff6579ff2c0$"Objeto · Precio base · Peso\nAbrojos (bolsa de 20) · 1 po · 2 lb\n\nAbrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_383ecff6579ff2c0$::jsonb,true),'{features}',$text_816adba2fd0e635e$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_816adba2fd0e635e$::jsonb,true),'{rules,definition,description}',$text_ad9e1c5eb1c88758$[{"id":"official-table","rows":[["Abrojos (bolsa de 20)","1 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_ad9e1c5eb1c88758$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:741c6683c6d99e0c4fd359ba';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:74a52ed7f52b736c3d425209' and md5(to_jsonb(t)::text)='d7ac64e75bca4cfc7160c1363b72933a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:74a52ed7f52b736c3d425209';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_75d1cfa2fedc4884$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este cubo mide 7,5 cm de lado e irradia una energía mágica palpable. Cada una de las seis caras del cubo está conectada con un plano de existencia diferente, entre ellos el Plano Material. El resto de planos los determina tu GM.\n\nPuedes utilizar una acción para pulsar un lado del cubo y lanzar el conjuro portal, de forma que se abra un portal hacia el plano conectado con esa cara. De forma alternativa, si utilizas una acción para pulsar una cara dos veces, puedes lanzar el conjuro desplazamiento entre planos (CD de salvación 17) con el cubo y transportar a los objetivos al plano conectado con esa cara.\n\nEl cubo tiene 3 cargas. Cada uso gasta 1 carga. El cubo recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_75d1cfa2fedc4884$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:74a52ed7f52b736c3d425209';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:74d803c9be726373ff91c34e' and md5(to_jsonb(t)::text)='cabab3e078dd04b4a7d893efe4096a53')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:74d803c9be726373ff91c34e';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_84e82a45a64001fe$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. También tiene las propiedades adicionales que se mencionan a continuación. Cuando se utilice una de ellas, no podrá volver a usarse hasta el siguiente amanecer.\n\nGolpe relampagueante. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás hacer que el objetivo sufra 2d6 de daño de relámpago adicional.\n\nGolpe atronador. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás hacer que el bastón emita un chasquido atronador que se oiga a 90 m de distancia. El objetivo impactado deberá superar una tirada de salvación de Constitución con CD 17 o quedará aturdido hasta el final de tu siguiente turno.\n\nRelámpago. Puedes utilizar una acción para que un relámpago surja de la punta del bastón en una línea de 1,5 m de ancho y 36 m de largo. Todas las criaturas situadas en la línea deberán hacer una tirada de salvación de Destreza con CD 17; sufrirán 9d6 de daño de relámpago si la fallan o la mitad del daño si la superan.\n\nTrueno. Puedes utilizar una acción para hacer que el bastón emita un trueno ensordecedor que se oiga a 180 m de distancia. Todas las criaturas situadas a 18 m o menos de ti (menos tú) deberán realizar una tirada de salvación de Constitución con CD 17. Si la fallan, sufrirán 2d6 de daño de trueno y quedarán ensordecidas durante 1 minuto. Si la superan, sufrirán la mitad del daño y no quedarán ensordecidas.\n\nTruenos y relámpagos. Puedes utilizar una acción para usar las propiedades “relámpago” y “trueno” a la vez. Hacer esto no consume el uso diario de esas propiedades, solo de esta.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_84e82a45a64001fe$::jsonb,true),'{rules,personalDescription}',$text_337fb70cdceea982$"Este bastón se puede utilizar como un bastón mágico que otorga una bonificación de +2 a las tiradas de ataque y daño realizadas con él. También tiene las siguientes propiedades adicionales. Cuando se utiliza una de estas propiedades, no se puede volver a utilizar hasta el siguiente amanecer.\n\nRelámpago. Cuando realizas un ataque cuerpo a cuerpo con el bastón, puedes provocar que el objetivo sufra 2d6 puntos de daño por relámpago adicionales.\n\nTrueno. Cuando golpeas con un ataque cuerpo a cuerpo usando el bastón, puedes hacer que éste emita un trueno que se oye a 300 pies de distancia. El objetivo al que golpeas debe superar una tirada de salvación de Constitución CD 17 o quedará aturdido hasta el final de tu siguiente turno.\n\nGolpe de relámpago. Puedes usar una acción para hacer que un rayo salte desde la punta del bastón en una línea de 5 pies de ancho y 120 pies de largo. Cada criatura en esa línea debe realizar una tirada de salvación de Destreza CD 17, y si falla, recibe 9d6 puntos de daño por rayo, o la mitad de daño si tiene éxito.\n\nTrueno. Puedes usar una acción para hacer que el bastón emita un trueno ensordecedor, audible hasta 600 pies. Cada criatura a 60 pies de ti (sin incluirte a ti) debe realizar una tirada de salvación de Constitución CD 17. Si la tirada falla, la criatura recibe 2d6 puntos de daño por trueno y queda ensordeceda durante 1 minuto. Si la tirada tiene éxito, la criatura recibe la mitad del daño y no queda ensordeceda.\n\nTrueno y relámpago. Puedes usar una acción para usar las propiedades Golpe de relámpago y Atronador al mismo tiempo. Al hacerlo, no se consume el uso diario de esas propiedades, solo el uso de esta."$text_337fb70cdceea982$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:74d803c9be726373ff91c34e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:769ff7952f0ed75b062d6044' and md5(to_jsonb(t)::text)='5fb2ecc48d7b6be2ba9713ab751efc1d')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:769ff7952f0ed75b062d6044';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_bff3bb03f6016afe$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto de “agrandar” del conjuro agrandar/reducir durante 1d4 horas (no requiere concentración). El color rojo del líquido de la poción se expande continuamente a partir de una gota diminuta para teñir el líquido transparente que la rodea. A continuación, se vuelve a contraer. Si agitas la botella, no se interrumpirá el proceso.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bff3bb03f6016afe$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:769ff7952f0ed75b062d6044';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:77c1a86f7bceca1fb79453c1' and md5(to_jsonb(t)::text)='fa298bf3c4be6c896a638b1cad58a504')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:77c1a86f7bceca1fb79453c1';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_80073a099c59bdfb$[{"id":"official-base-table","rows":[["Lanza","1 po","3 lb","1d6 perforante","+0","Arrojadiza, Versátil","20/60","1d8"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_80073a099c59bdfb$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_0170730ceade80f6$["official-base-table","property-thrown","property-versatile","family-rule"]$text_0170730ceade80f6$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:77c1a86f7bceca1fb79453c1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:784bd660a08f0f45bc4bd35e' and md5(to_jsonb(t)::text)='a9321e4617768aef7d1c060cf43a6cb0')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:784bd660a08f0f45bc4bd35e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_f8d4aa1b82e82ffc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar el conjuro proyectil mágico desde ella. Si empleas 1 carga, podrás lanzar la versión de nivel 1 del conjuro. Puedes aumentar el nivel del espacio de conjuro en 1 por cada carga adicional que emplees.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f8d4aa1b82e82ffc$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:784bd660a08f0f45bc4bd35e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:787b7ce6af1d2525c342d664' and md5(to_jsonb(t)::text)='e28b45067cf80ea218096b1506ea524f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:787b7ce6af1d2525c342d664';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_53c7703c439bc2cd$[{"id":"mundane-assisted-use","kind":"other","name":"Proyectiles de la bolsa","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"La bolsa contiene 20 balas de honda. El precio y peso corresponden a la bolsa completa.\n\nDuración: Según su uso..","showInActions":false}]$text_53c7703c439bc2cd$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:787b7ce6af1d2525c342d664';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:78a330dcbaa0773138491e90' and md5(to_jsonb(t)::text)='e5f0e590511eb9d32570dce832f6573a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:78a330dcbaa0773138491e90';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a48d0c039253fa2$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:78a330dcbaa0773138491e90';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79852c0176e7952ae8226dcc' and md5(to_jsonb(t)::text)='20c784cf58aece092a9f2381235e3536')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:79852c0176e7952ae8226dcc';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a48d0c039253fa2$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79852c0176e7952ae8226dcc';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79a0a5ea6cf16922cb5a78f7' and md5(to_jsonb(t)::text)='e1ca9966ad6addc2c22cb3dae7ae0d46')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:79a0a5ea6cf16922cb5a78f7';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_57266ba65d589236$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un gigante con ella, el gigante sufrirá 2d6 de daño adicional del tipo del arma y deberá superar una tirada de salvación de Fuerza con CD 15 o caerá derribado. En lo que concierne a esta arma, “gigante” se refiere a cualquier criatura con el tipo “gigante”, incluidos seres como ettins y trolls.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_57266ba65d589236$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79a0a5ea6cf16922cb5a78f7';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79ac3b7e18f9352b31f1cde4' and md5(to_jsonb(t)::text)='e60fa417119827958c5f1f9c2c17bd7a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:79ac3b7e18f9352b31f1cde4';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_f22a284ca7ab083d$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas botas forradas de pelaje son ceñidas y calentitas. Mientras las lleves puestas, obtendrás los siguientes beneficios: • Tienes resistencia al daño de frío. • El terreno difícil creado por hielo o nieve no te afecta. • Puedes aguantar temperaturas de hasta –45 °C sin más protección. Si llevas ropas pesadas, puedes soportar hasta –75 °C.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f22a284ca7ab083d$::jsonb,true),'{rules,personalDescription}',$text_f7b471beabad753e$"Estas botas forradas de pelaje son ceñidas y calentitas. Mientras las lleves puestas, obtendrás los siguientes beneficios:\nResistencia al daño de frío.\nIgnoras el terreno difícil por nieve o hielo\nPuedes aguantar temperaturas de hasta -45 ºC sin más protección. Si llevas ropas pesadas, puedes soportar hasta - 75 ºC."$text_f7b471beabad753e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:79ac3b7e18f9352b31f1cde4';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7a41873e8602ad756e91bf15' and md5(to_jsonb(t)::text)='8fd2faf9cb8ce5c47f6d6291a449c316')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7a41873e8602ad756e91bf15';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_5d969e1c90876246$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este amuleto, podrás usar una acción para nombrar un lugar que conozcas de otro plano de existencia. Después, haz una prueba de Inteligencia con CD 15. Si la superas, lanzarás el conjuro desplazamiento entre planos. Si la fallas, tú y cualquier criatura y objeto que esté a 4,5 m o menos de ti os desplazaréis a un destino aleatorio. Tira 1d100. Si sacas entre 1 y 60, viajáis a un lugar aleatorio en el plano de existencia nombrado. Si sacas entre 61 y 100, aparecéis en un plano determinado al azar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5d969e1c90876246$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7a41873e8602ad756e91bf15';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7c1a658894dfd5edf11c9260' and md5(to_jsonb(t)::text)='c580b5aa2a3fb9f22d9b66aec9be65a5')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7c1a658894dfd5edf11c9260';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_8b05c428c79f2f94$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta sustancia viscosa y blanca como la leche puede crear un vínculo adhesivo permanente entre dos objetos cualesquiera. Debe almacenarse en un bote o frasco que se haya untado con aceite escurridizo. En el momento de encontrar el recipiente, contendrá 30 g + 1d6 × 30 g.\n\n30 g de pegamento pueden cubrir una superficie cuadrada de 30 cm de lado. El pegamento tarda 1 minuto en asentarse. En cuanto lo haga, el vínculo que crea solo se puede romper si se aplica un disolvente universal o un aceite de etereidad o con un conjuro deseo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8b05c428c79f2f94$::jsonb,true),'{rules,personalDescription}',$text_7c145f46337e29a5$"Esta sustancia viscosa y blanca como la leche es capaz de formar un vínculo adhesivo permanente entre dos objetos cualesquiera. Debe ser almacenada en un frasco o bote que haya sido untado con una capa de aceite escurridizo. En el momento de encontrar el recipiente, a este le quedarán 1d6 + 1 onzas.\n\nUna onza de pegamento puede cubrir una superficie de 1 pie cuadrado. Tarda un minuto en asentarse y hacer efecto. Una vez asentado, el vínculo creado solo puede romperse aplicando disolvente universal o aceite de etereidad, o mediante el conjuro deseo."$text_7c145f46337e29a5$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7c1a658894dfd5edf11c9260';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7c5164541d5c7d2d1179ff8e' and md5(to_jsonb(t)::text)='00c647cf3ce2b212471808cefa534069')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7c5164541d5c7d2d1179ff8e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_447d1b12fca0c2f9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta vara de hierro posee un botón en uno de sus extremos. Puedes usar una acción para pulsar el botón y hacer que la vara se fije mágicamente en el sitio. Hasta que otra criatura o tú utilicéis una acción para pulsar de nuevo el botón, la vara no se moverá, desafiando a la gravedad si es necesario. Puede aguantar hasta 4000 kg de peso; una cantidad mayor provocará que se desactive y caiga. Una criatura puede usar su acción para realizar una prueba de Fuerza con CD 30. Si tiene éxito, moverá la vara hasta 3 m.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_447d1b12fca0c2f9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7c5164541d5c7d2d1179ff8e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7d150b153865ce199ca4823c' and md5(to_jsonb(t)::text)='8a110b3af7df5cf80e76b17248957e0a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7d150b153865ce199ca4823c';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_13c2783a0f6c5ecf$"Objeto · Precio base · Peso\nAmuleto · 5 po · 1 lb\n\nSímbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_13c2783a0f6c5ecf$::jsonb,true),'{features}',$text_20d6da3fc6e17a06$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_20d6da3fc6e17a06$::jsonb,true),'{rules,definition,description}',$text_a2a80e2fdb6b3797$[{"id":"official-table","rows":[["Amuleto","5 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_a2a80e2fdb6b3797$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7d150b153865ce199ca4823c';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 5 as batch,44 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;